# Сборка data/subjects/arch/pc.json — какие задания Архитектуры в каком «приложении» компьютера и как их проверять.
# EWB-часть берётся из базы сайта (visuals: ewb_build_task / ewb_circuit / ewb_from_expression…), ответы для «Тетради» — вручную ниже.
# Запуск: python data/subjects/arch/pc-build.py "<путь к architecture_base.json>"
import json, io, sys, os
HERE = os.path.dirname(os.path.abspath(__file__))
base = json.load(io.open(sys.argv[1], encoding='utf-8'))
labs = json.load(io.open(os.path.join(HERE, 'labs.json'), encoding='utf-8'))
asm = json.load(io.open(os.path.join(HERE, 'asm.json'), encoding='utf-8'))

def H(l, *a): return {'l': l, 'a': list(a), 'k': 'hex'}
def B(l, *a): return {'l': l, 'a': list(a), 'k': 'bin'}
def N(l, a, tol=0.0, u=''): return {'l': l, 'a': [a], 'k': 'num', 'tol': tol, 'u': u}
def T(l, *a): return {'l': l, 'a': list(a), 'k': 'text'}
def S(l, ref): return {'l': l, 'a': [ref], 'k': 'self'}
def TT(l, vars_, tt): return {'l': l, 'k': 'tt', 'v': vars_, 'tt': tt}
def L(l, *a): return {'l': l, 'a': list(a), 'k': 'list'}

