GEN = { 't10-c1': 'cache', 't10-c2': 'cache', 't10-c3': 'cache', 't10-a1': 'amat', 't10-a2': 'amat', 't2-z4': 'ieee', 't7-z3': 'modM' }
TOOL = { 't1': 'numCalc', 't2': 'ieeeCalc', 't4': 'kmapCalc', 't5': 'adderSim', 't6': 'ffSim', 't7': 'cntSim', 't10': 'cacheAddr', 't11': 'ramCalc', 't12': 'segCalc', 't13': 'hammingCalc', 't14': 'busCalc', 't15': 'irqSim', 't9': 'amatCalc' }
TOOL_ID = { 't10_lab2_task1': 'amatUnits', 't10-a1': 'amatUnits', 't10-a2': 'amatUnits', 't9-z4': 'amatCalc', 't4_lab1_task3': 'logicCalc', 't4-z5': 'kmapCalc', 't13-z1': 'segCalc' }

vis = {}
for t in base['topics']:
    for l in t['labs']:
        for k in l['tasks']:
            vis[k['id']] = [v for v in (k.get('visuals') or []) if v]

out = {}
for l in labs:
    n = l['topic']
    for t in l['tasks']:
        tid = t['id']; V = vis.get(tid, []); o = {}
        builds, refs, tool = [], [], None
        for v in V:
            ty = v['type']
            if ty == 'ewb_build_task': builds.append({'t': v['task']})
            elif ty == 'ewb_circuit': refs.append({'c': v['key']})
            elif ty == 'ewb_from_expression': refs.append({'x': v['expr'], 'o': 'y', 'n': 'Схема по формуле'}); builds.append({'e': v['expr'], 'o': 'y'})
            elif ty == 'ewb_from_expression_list':
                for it in v['items']:
                    refs.append({'x': it['expr'], 'o': it.get('out') or 'y', 'n': it.get('title', '')})
            elif ty == 'calculator': tool = v['id']
        if (builds or refs) and tid not in ITEMS:
            o['app'] = 'ewb'
        elif tid in asm.get('tasks', {}):
            o['app'] = 'asm'; o['asm'] = asm['tasks'][tid]
        elif tid in ITEMS or tid in GEN:
            o['app'] = 'calc'
        elif 3 <= n <= 7:
            o['app'] = 'ewb'; o['read'] = 1          # теория EWB-тем — в EWB, рядом со свободной студией
        elif n == 8:
            o['app'] = 'asm'; o['read'] = 1
        else:
            o['app'] = 'note'
        if tid in ('t9-z1', 't11-z1', 't12-z1', 't14-z3'): o['app'] = 'note'; o['pc'] = 1   # «свой компьютер»
        if tid == 't8-z28': o = {'app': 'note'}   # контрольные вопросы — карточки в блокноте
        if o['app'] == 'ewb':
            # из формул без build-задания делаем «собери по формуле» (с автопроверкой) — по одной на каждую новую формулу
            if not builds:
                for r in refs:
                    if 'x' in r: builds.append({'e': r['x'], 'o': r['o'], 'n': r['n']})
            seen = set(); bl = []
            for b in builds:
                k = b.get('t') or b.get('e')
                if k in seen: continue
                seen.add(k); bl.append(b)
            if bl and not o.get('read'): o['builds'] = bl[:12]
            if refs: o['refs'] = refs[:14]
        if tid in ITEMS: o['items'] = ITEMS[tid]
        if tid in GEN: o['gen'] = GEN[tid]
        o['tool'] = TOOL_ID.get(tid) or tool or (TOOL.get('t' + str(n)) if o['app'] == 'calc' else None)
        if not o['tool']: del o['tool']
        if o['app'] == 'ewb' and tid == 't7-z3': o['gen'] = 'modM'
        out[tid] = o

# t7-z3: и сборка, и расчёт модуля
from collections import Counter
print(Counter(v['app'] for v in out.values()))
io.open(os.path.join(HERE, 'pc.json'), 'w', encoding='utf-8').write(json.dumps({'tasks': out}, ensure_ascii=False, separators=(',', ':')))
